WITH v AS (SELECT strftime('%Y-%m',p.fecha) mes,c.ruta,SUM(i.cantidad*i.precio_unitario) ventas FROM pedidos p JOIN pedido_items i USING(pedido_id) JOIN clientes c USING(cliente_id) WHERE p.estado='entregado' GROUP BY mes,c.ruta) SELECT b.mes,b.ruta,ROUND(COALESCE(v.ventas,0),2) ventas,b.presupuesto_bs,ROUND(100.0*COALESCE(v.ventas,0)/NULLIF(b.presupuesto_bs,0),2) cumplimiento FROM presupuesto b LEFT JOIN v ON v.mes=b.mes AND v.ruta=b.ruta ORDER BY b.mes,b.ruta;
